async function api(path, signal) {return requestData(path,{signal});}
async function load(force=false, quiet=false) {
  const id=++requestId;controller?.abort();controller=new AbortController();state.loading=true;state.error=null;
  const selection=[state.view,state.market,state.season,state.week].join(':');
  if(!quiet&&selection!==loadedSelection)state.data=null;
  renderChrome();renderContent();
  try {
    const q=new URLSearchParams({view:['metrics','trends'].includes(state.view)?'board':state.view,market:state.market});
    if(state.season!==null){q.set('season',state.season);q.set('week',state.week);}if(force)q.set('refresh','1');
    const data=await api('/api/board?'+q,controller.signal);if(id!==requestId)return;
    state.data=data;loadedSelection=selection;state.catalog={weeks:data.weeks,current:data.weeks[0]};state.loading=false;render();
    lastAutoCheck=Date.now();
    if(force)toast(data.availability?.stale?'Injury refresh failed. Last known statuses retained; new leans withheld.':data.stale?'A stats source is unavailable. Showing saved statistics.':data.availability?.applied?'Data and ESPN injury report refreshed.':'Data refreshed.');
  } catch(error) { if(error.name==='AbortError'||id!==requestId)return;state.loading=false;state.error=error.message;render(); }
}
