function lineNumber(n){return Number.isFinite(n)?String(n):'—';}
function basisLabel(p){return p.prop?.basis==='captured_pregame'?'Saved before kickoff':p.prop?.basis==='published_archive'?'Archived listing':p.prop?.basis==='in_play'?'In-play reference':'Line not posted';}
function resultBadge(p){const r=p.result;if(!r||r.status==='pending')return '';const names={over:state.market==='any_td'?'TD SCORED':'OVER HIT',under:state.market==='any_td'?'NO TD':'OVER MISSED',push:'PUSH',no_line:'NO LINE TO GRADE',no_stats:'FINAL STATS MISSING',did_not_play:'DID NOT PLAY'};return `<span class="result-badge ${esc(r.status)}">${esc(names[r.status]||'FINAL')}${Number.isFinite(r.actual)?` · ${r.actual} ${esc(r.unit)}`:''}</span>`;}
